def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# Compute F_k for k=2 up to k=20
F = {}
for k in range(2, 21):
    F[k] = fibonacci(k)

print("Fibonacci numbers F_2 to F_20:")
print(F)

# Target set D = {F_2, F_3, ..., F_10}
D = [F[k] for k in range(2, 11)]
print("\nTarget differences D = {F_2, ..., F_10}:")
