import numpy as np

S = [0, 1, 2, 3, 5, 8, 13, 21, 34, 55]
differences = set()
for i in range(len(S)):
    for j in range(i + 1, len(S)):
        differences.add(S[j] - S[i])

required_fibs = {1, 2, 3, 5, 8, 13, 21, 34, 55}

is_covered = required_fibs.issubset(differences)
print(f"Set S: {S}")
print(f"Required Fibs covered: {is_covered}")
if not is_covered:
    print(f"Missing differences: {required_fibs - differences}")

